import{_ as t,o,c as r,ae as a}from"./chunks/framework.Bs_1Tt6f.js";const c=JSON.parse('{"title":"Importing OMMR4all Data","description":"","frontmatter":{},"headers":[],"relativePath":"docs/ommr-import.md","filePath":"docs/ommr-import.md"}'),n={name:"docs/ommr-import.md"};function s(i,e,l,p,h,m){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="importing-ommr4all-data" tabindex="-1">Importing OMMR4all Data <a class="header-anchor" href="#importing-ommr4all-data" aria-label="Permalink to &quot;Importing OMMR4all Data&quot;">​</a></h1><p>If your manuscript was processed with <strong>OMMR4all</strong>, you can bring its neume positions into the app as snippets instead of drawing them by hand. Open <strong>Import Dataset</strong> (OMMR) in the menu.</p><h2 id="importing" tabindex="-1">Importing <a class="header-anchor" href="#importing" aria-label="Permalink to &quot;Importing&quot;">​</a></h2><ol><li><strong>Select the target manuscript.</strong> Choose one of the manuscripts already in your project, let the app <strong>auto-detect</strong> it from the folder name (for example <code>Pa_14819</code> → <code>Pa 14819</code>), or enter a new name.</li><li><strong>Choose the OMMR folder.</strong> Pick the export directory that contains the <code>pcgts.json</code> files (one per page). Colour page images in the folder are used for exact local crops; otherwise the app cuts the snippets from the IIIF images.</li></ol><p>The app reads every page, maps the OMMR page names to folios, and lists all neumes by pattern.</p><h2 id="working-with-the-result" tabindex="-1">Working with the result <a class="header-anchor" href="#working-with-the-result" aria-label="Permalink to &quot;Working with the result&quot;">​</a></h2><ul><li>Browse patterns in the sidebar and look at their snippets.</li><li>Select snippets and <strong>import</strong> them: they are stored in your annotations as snippets inside line regions, like ones you drew yourself. Importing the same selection again adds nothing new.</li><li>The <strong>settings drawer</strong> controls how thumbnails look (context around the neume, markers, IIIF vs. local images), and holds the folio <strong>calibration</strong>, <strong>folio offsets</strong> and <strong>index modes</strong> that line OMMR pages up with your folios. These are saved in your workspace and backups.</li><li>If the manuscript was matched to the wrong source, use <strong>Project Source</strong> in the drawer to remap it.</li></ul>',7)])])}const g=t(n,[["render",s]]);export{c as __pageData,g as default};
